def coloring_page_fragment(
    day_label: str, brand: str, subtitle: str, fact: str, img_b64: str
) -> str:
    """A hand-built fragment for the bonus coloring pages -- not part of the typed worksheet
    kinds (these are static images, not structured data), so this composes plain HTML directly
    against the shared packet CSS classes instead of going through render_worksheet_html."""
    primary, light = get_day_palette(day_label)
    return f"""
<div class="day-header" style="background:{primary};">
  <div class="day-header-label">Bonus</div>
  <div class="day-header-title">Coloring Page</div>
</div>
<div class="ws-title" style="color:{primary};border-bottom-color:{primary};">{brand}</div>
<div class="ws-instructions">{subtitle} &mdash; grab your crayons or markers and color it in!</div>
<div style="text-align:center;margin:10px 0;">
  <img src="{img_b64}" style="max-width:92%;max-height:8.6in;border:2px solid {primary};
       border-radius:8px;background:white;" alt="{brand} coloring page">
</div>
<div style="font-size:9.5pt;color:#555;font-style:italic;border-top:1px dashed #bbb;
     padding-top:8px;margin-top:6px;">Real-world fact: {fact}</div>
"""


